import { __setServerRuntime, getDir } from 'next-tongue/server';
// Generated by `tongue build` (runs before next build).
// @ts-expect-error — generated JS until codegen emits .d.ts beside ns modules
import { messages as homeMessages } from '../.tongue/ns/home.js';

const LOCALES = ['en', 'de'] as const;
export type AppLocale = (typeof LOCALES)[number];

const NAMESPACES: Record<
  string,
  Record<string, (locale: string, values?: Record<string, unknown>) => string>
> = {
  home: homeMessages as Record<
    string,
    (locale: string, values?: Record<string, unknown>) => string
  >,
};

let ready = false;

export function isAppLocale(value: string): value is AppLocale {
  return (LOCALES as readonly string[]).includes(value);
}

export function localeStaticParams(): { locale: AppLocale }[] {
  return LOCALES.map((locale) => ({ locale }));
}

export async function ensureTongueRuntime(): Promise<void> {
  if (ready) return;
  __setServerRuntime({
    locales: LOCALES,
    defaultLocale: 'en',
    timeZone: 'UTC',
    loadNamespace: async (namespace) => {
      const messages = NAMESPACES[namespace];
      if (!messages) {
        throw new Error(`[example] Unknown namespace: ${namespace}`);
      }
      return messages;
    },
  });
  ready = true;
}

export { getDir };
